const COMPETITION_WEIGHT: Record<CompetitionLevel, number> = {
  Low: 3,
  Medium: 2,
  High: 1,
  Unknown: 1,
};

const INTENT_WEIGHT: Record<KeywordIntent, number> = {
  transactional: 3,
  comparative: 2,
  informational: 1,
};

/**
 * Compute a priority score for an arbitrary keyword.
 * Higher volume + lower competition + commercial intent = higher score.
 */
export function keywordScore(
  avgMonthlySearches: number,
  competition: CompetitionLevel,
  intent: KeywordIntent
): number {
  return (
    (avgMonthlySearches / 10) *
    COMPETITION_WEIGHT[competition] *
    INTENT_WEIGHT[intent]
  );
}

/**
 * Return keywords matching a search term (case-insensitive substring).
 */
export function searchKeywords(query: string): KeywordEntry[] {
  const q = query.toLowerCase();
  return keywordCatalog.filter((k) => k.keyword.toLowerCase().includes(q));
}

/**
 * Top-N keywords by priority score, optionally filtered by intent.
 */
export function topKeywords(
  limit: number,
  intent?: KeywordIntent,
  competition?: CompetitionLevel
): KeywordEntry[] {
  const filtered = keywordCatalog.filter(
    (k) =>
      (!intent || k.intent === intent) &&
      (!competition || k.competition === competition)
  );
  return filtered
    .sort((a, b) => b.score - a.score)
    .slice(0, limit);
}

/**
 * Keywords mentioning a specific competitor or tool name.
 */
export function keywordsForCompetitor(competitor: string): KeywordEntry[] {
  const q = competitor.toLowerCase();
  return keywordCatalog.filter(
    (k) => k.keyword.toLowerCase().includes(q)
  );
}

/**
 * Intent distribution across the whole catalog (for reporting).
 */
export function intentDistribution(): Record<KeywordIntent, number> {
  const counts: Record<KeywordIntent, number> = {
    transactional: 0,
    comparative: 0,
    informational: 0,
  };
  for (const k of keywordCatalog) counts[k.intent]++;
  return counts;
}

/**
 * Competition distribution across the whole catalog (for reporting).
 */
export function competitionDistribution(): Record<CompetitionLevel, number> {
  const counts: Record<CompetitionLevel, number> = {
    Low: 0,
    Medium: 0,
    High: 0,
    Unknown: 0,
  };
  for (const k of keywordCatalog) counts[k.competition]++;
  return counts;
}
